(69,'H5P.OpenEndedQuestion','Open Ended Question',1,0,28,0,0,'','dist/h5p-open-ended-question.js','dist/h5p-open-ended-question.css','','[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question or description\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"default\": \"Start writing...\",\n    \"importance\": \"low\",\n    \"description\": \"Text that initially will be shown in the input field. Will be removed automatically when the user starts writing.\",\n    \"type\": \"text\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"inputRows\",\n    \"label\": \"Input rows\",\n    \"type\": \"select\",\n    \"importance\": \"high\",\n    \"description\": \"Determines the height of the input field.\",\n    \"options\": [\n      {\n        \"value\": \"1\",\n        \"label\": \"1 line\"\n      },\n      {\n        \"value\": \"2\",\n        \"label\": \"2 lines\"\n      },\n      {\n        \"value\": \"3\",\n        \"label\": \"3 lines\"\n      },\n      {\n        \"value\": \"10\",\n        \"label\": \"10 lines\"\n      }\n    ],\n    \"default\": \"1\"\n  }\n]',NULL,NULL,NULL,NULL,NULL,NULL,1),
